const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(v,d=2)=>Number.isFinite(v)?new Intl.NumberFormat('ko-KR',{maximumFractionDigits:d,minimumFractionDigits:d}).format(v):'—';
const when=value=>value?new Date(value).toISOString().slice(0,16).replace('T',' ')+' UTC':'—';
const button=(label,op,id='',style='',disabled=false)=>`<button type="button" class="button ${style}" data-op="${op}" data-id="${esc(id)}"${disabled?' disabled aria-busy="true"':''}>${label}</button>`;
const field=(label,name,value='',type='text',extra='')=>`<label class="field">${label}<input name="${name}" type="${type||'text'}" value="${esc(value)}" ${extra}></label>`;
const area=(label,name,value='',max=6000)=>`<label class="field full">${label}<textarea name="${name}" maxlength="${max}" required>${esc(value)}</textarea></label>`;
const select=(label,name,items,selected='')=>`<label class="field">${label}<select name="${name}">${items.map(([id,label])=>`<option value="${esc(id)}" ${id===selected?'selected':''}>${esc(label)}</option>`).join('')}</select></label>`;
const details=value=>`<details class="spaced"><summary>기록 상세</summary><pre class="code">${esc(JSON.stringify(value,null,2))}</pre></details>`;
const panel=(title,body,actions='')=>`<section class="panel section"><div class="panel-head"><h2>${title}</h2>${actions}</div><div class="panel-body">${body}</div></section>`;
const table=(heads,rows)=>`<div class="table-scroll"><table class="table"><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const knowledgeTypes=[['OBSERVED_FACT','관측 사실'],['HYPOTHESIS','가설'],['VALIDATED_HEURISTIC','검증된 경험칙'],['OPERATING_PROCEDURE','운영 절차']];
