  let data=null,market=null,error='',busy=false,selectedProfile=null,started=false,busyDeployment=null,busyOperation=null,refreshing=false,pollTimer=null;const times=new Map(),pending=new Map(),blockedDecisions=new Set();
  const workspace=()=>data, choose=(array,id)=>array.find(v=>v.id===id), getVersion=(versions,entity)=>choose(versions,entity.currentVersionId), redraw=()=>hooks.render();
  async function request(path,body,{signal}={}){const r=await fetch(path,{method:body?'POST':'GET',cache:'no-store',signal,headers:{'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});let value;try{value=await r.json();}catch{const e=new Error('서버 응답을 확인하지 못했습니다. 다시 조회해 저장된 처리 단계부터 이어서 실행하세요.');e.code='RESPONSE_UNAVAILABLE';throw e;}if(!r.ok||value.ok===false){const e=new Error(value.message||'요청을 확인하세요.');e.code=value.code;e.availability=value.availability;e.resetCursor=value.resetCursor;e.diagnostic=value.diagnostic;throw e;}return value;}
  async function refresh({quiet=false}={}){if(busy||refreshing)return;refreshing=true;if(!quiet){busy=true;error='';redraw();}let changed=false;try{const value=await request('/api/workspace');if(!data||value.workspace.revision>=data.revision){changed=!data||value.workspace.revision!==data.revision;data=value.workspace;market=value.market;}}catch(e){if(!quiet)error=e.message;}finally{refreshing=false;if(!quiet)busy=false;if(!quiet||changed)redraw();}}
  async function action(type,payload,endpoint='/api/workspace/actions'){
    if(busy||!data)return;if(endpoint.endsWith('/evaluate')){const prior=data.decisionRecords.filter(r=>r.deploymentId===payload.deploymentId).at(-1);if(prior)blockedDecisions.add(prior.id);}busyDeployment=payload.deploymentId??null;busyOperation=endpoint.endsWith('/jobs/run')?'jobs-run':null;busy=true;error='';redraw();const fingerprint=JSON.stringify({type,payload,endpoint});const key=pending.get(fingerprint)||crypto.randomUUID();pending.set(fingerprint,key);
    try{const body=endpoint.endsWith('/actions')?{type,payload,idempotencyKey:key,expectedRevision:data.revision}:{...payload,idempotencyKey:key,expectedRevision:data.revision};const value=await request(endpoint,body);data=value.workspace;pending.delete(fingerprint);hooks.close();hooks.toast('저장했습니다.');return value.result;}catch(e){error=e.message;hooks.toast(e.message);try{const latest=await request('/api/workspace');data=latest.workspace;}catch{}throw e;}finally{busy=false;busyDeployment=null;busyOperation=null;redraw();}
  }
  const investmentConsole=createInvestmentConsole({getWorkspace:workspace,getMarket:()=>market,getDataset:()=>hooks.getDataset?.(),getBusy:()=>busy,getError:()=>error,action,request,refresh,open:hooks.open,close:hooks.close,toast:hooks.toast,navigate:hooks.navigate,render:redraw,configureBot:configureBotForm,reviewExperience,reviewCandidate,navigateExperience:profileId=>{selectedProfile=profileId;hooks.navigate('profiles');requestAnimationFrame(()=>document.getElementById('profile-memory')?.scrollIntoView({block:'start'}));}});
  function form(title,body,kind,id=''){hooks.open(title,`<form data-op-form="${kind}" data-id="${esc(id)}"><div class="form-grid">${body}</div><div class="error-text spaced" role="alert" data-op-error></div><div class="form-actions"><button class="button primary" type="submit">저장</button></div></form>`);}
