  function profileCards(){return panel('투자 원칙',table(['프로필','원칙','투자 기간','최신 버전',''],data.investmentProfiles.map(p=>{const v=getVersion(data.profileVersions,p),memory=choose(data.memoryVersions,p.currentMemoryVersionId);return [esc(p.name),esc(v.settings.philosophy),esc(({'1h':'1시간','4h':'4시간','1d':'일 단위','multi-day':'여러 날'})[v.settings.horizon]||v.settings.horizon),`프로필 v${v.version} · 기억 v${memory?.version??0}`,`<div class="actions">${button('편집','profile-edit',p.id,'small')}${button('복제','profile-clone',p.id,'small')}${button('경험·지식','profile-memory',p.id,'small')}</div>`];})));}
