  function activityPage(){return header('활동 내역','설정·승인·실행·체결의 서버 기록을 확인합니다.')+panel('활동',table(['시각','활동','대상',''],data.activityEvents.slice(-100).reverse().map(e=>[when(e.occurredAt),esc(({DEPLOYMENT_EVALUATION_STARTED:'선택 실행 시작',JEV_REQUEST_STARTED:'JEV 요청',JEV_REQUEST_COMPLETED:'JEV 완료',JEV_REQUEST_FAILED:'JEV 실패',WORKSPACE_RESOURCE_CHANGED:'자료 변경',FILL_RECORDED:'체결 기록',MEMORY_APPROVED:'기억 승인',DEPLOYMENT_CONFIGURED:'적용 버전 변경'})[e.eventType]||({PROFILE_CREATED:'프로필 추가',PROFILE_CLONED:'프로필 복제',PROFILE_REVISED:'프로필 수정',STRATEGY_CREATED:'전략 추가',STRATEGY_REVISED:'전략 수정',PRESET_CREATED:'프리셋 추가',PRESET_REVISED:'프리셋 수정',DEPLOYMENT_CREATED:'운용 봇 생성',BOT_STARTED:'운용 시작',BOT_PAUSED:'운용 일시중지',BOT_STOPPED:'운용 중지',DECISION_SAVED:'선택 결과 저장',EXPERIENCE_RECORDED:'경험 기록',EXPERIENCE_EVALUATED:'경험 평가',MEMORY_CANDIDATE_CREATED:'학습 후보 작성',PROPOSAL_INVALIDATED:'주문 제안 해제',PAPER_ORDER_SUBMITTED:'모의 주문',DEPLOYMENT_OPERATION_FAILED:'실행 실패',SCHEDULED_JOB_STATE_CHANGED:'예약 작업 갱신',SHARED_ACCOUNT_CREATED:'공유 계좌 생성',DEPLOYMENT_SHARED_ACCOUNT_ATTACHED:'공유 자금 연결',SHARED_ACCOUNT_RECONCILED:'공유 잔고 대조',SHARED_RISK_CHECKED:'공유 계좌 한도 확인',SHARED_FILL_MIRRORED:'공유 체결 반영'})[e.eventType]||'활동 기록'),esc(({profile:'투자 프로필',strategy:'전략',preset:'운용 프리셋',deployment:'운용 봇',decision:'선택 결과',experience:'경험',candidate:'학습 후보',fill:'체결',workspace:'리서치',scheduler:'예약 작업','shared-account':'공유 계좌'})[e.resourceType]||'투자 기록'),button('상세','event-detail',e.id)])));}
  function strategyPanel(){return panel('전략 버전',table(['전략','선택 방식','결합 규칙','버전',''],data.strategies.map(s=>{const v=getVersion(data.strategyVersions,s);return [esc(s.name),v.settings.provider==='jev'?'JEV':'가격 구조',v.settings.fusionMode==='confirmatory'?'일치 확인':'참고',`v${v.version}`,button('편집','strategy-edit',s.id)];})),button('전략 추가','strategy-new'))+panel('운용 프리셋',table(['프리셋','보통 / 기회 집중','최대 보유','일일 손실 한도',''],data.riskPresets.map(p=>{const v=getVersion(data.riskPresetVersions,p).settings;return [esc(p.name),`${num(v.normalBuyWeight*100,0)}% / ${num(v.clutchBuyWeight*100,0)}%`,num(v.maxExposure*100,0)+'%',num(v.dailyLossLimit*100,1)+'%',button('편집','preset-edit',p.id)];})),button('프리셋 추가','preset-new'));}
