  const invalidated=record=>{if(blockedDecisions.has(record.id))return true;const latest=data.activityEvents.filter(e=>e.eventType==='DEPLOYMENT_EVALUATION_STARTED'&&e.resourceId===record.deploymentId).at(-1);return latest&&latest.payload.commandKey!==record.inputPackage.executionCommandKey;};
  const versionsMatch=(record,d)=>['investmentProfileVersionId','strategyVersionId','riskPresetVersionId','memoryVersionId'].every(k=>record[k]===d[k]);
  const consumed=(record,account)=>record&&account.ledger.some(f=>f.decisionId===record.id);
