  function evaluateExperienceForm(id){const e=choose(data.experiences,id),o=e.observation;return form('경험 평가',(e.experienceType==='EXECUTION_OPERATION'?'<div class="full callout"><p>'+esc(o.details)+'</p></div>':'<div class="full callout"><p>관측 종가 '+num(o.price)+' · 최고 '+num(o.maxPrice)+' · 최저 '+num(o.minPrice)+'</p><p>기준 가격 대비 '+num((o.price/e.referencePrice-1)*100)+'%</p><p class="tiny">'+esc(o.details)+'</p></div>')+(o.performance?'<div class="full callout"><strong>선택 후 '+o.horizonHours+'시간 진단</strong><p>'+esc(o.performance.assumption)+'</p><p>순수익률 '+num(o.performance.netReturn*100)+'% · 유지 대조 '+num(o.performance.benchmarks.holdingReturn*100)+'% · 현금 대조 '+num(o.performance.benchmarks.allCashReturn*100)+'%</p><p>반영 비용 '+num(o.performance.feesPaid)+' USDT · 연결 체결 '+o.performance.fillIds.length+'건</p></div>':'')+area('평가 요약','summary',outcomeSummary(e)+' · 선택 근거와 대조 결과, 반례를 기록한다.'),'evaluate',id);}
  function memoryCandidateForm(id){
    const e=choose(data.experiences,id),eligible=data.experiences.filter(v=>v.status==='EVALUATED'&&v.investmentProfileId===e.investmentProfileId&&v.deploymentId===e.deploymentId&&v.experimentId===e.experimentId&&v.experienceType===e.experienceType),experiences=[...eligible.filter(v=>v.id===id),...eligible.filter(v=>v.id!==id).sort((a,b)=>Date.parse(b.occurredAt)-Date.parse(a.occurredAt))].slice(0,50);
    const experiencePicker='<label class="field full">근거 경험<select name="experienceIds" multiple size="'+Math.min(8,Math.max(3,experiences.length))+'" required aria-describedby="memory-experience-scope">'+experiences.map(v=>{const p=v.observation?.performance,diagnostic=p&&Number.isFinite(p.netReturn)?'선택 후 '+(v.observation.horizonHours||24)+'시간 진단 '+num(p.netReturn*100)+'%':v.experienceType==='EXECUTION_OPERATION'?'운영 경험':'진단 자료 없음';return '<option value="'+esc(v.id)+'"'+(v.id===id?' selected':'')+'>'+esc(when(v.occurredAt)+' · '+diagnostic+' · '+v.summary.slice(0,140))+'</option>';}).join('')+'</select></label><p id="memory-experience-scope" class="tiny full muted">같은 프로필·운용 봇·실험·경험 유형의 평가 완료 기록을 최대 50개 표시합니다. 반복 사례와 반례를 함께 선택하세요. 중복·겹친 기간은 독립 표본 추가 검토가 필요합니다.</p>';
    return form('학습 후보 작성',field('제목','title',when(e.occurredAt)+' 관측 검토','text','required')+select('지식 유형','knowledgeType',knowledgeTypes,'HYPOTHESIS')+experiencePicker+area('조건·내용·적용 범위','text',e.evaluation?.summary||'')+'<p class="tiny full">연결된 실제 경험에서 표본 수·기간·비용·성과를 계산합니다. 검증된 경험칙은 실시간 후속 관측과 검증 계획·반례·불확실성 검토를 요구합니다.</p>'+(e.experienceType==='EXECUTION_OPERATION'?area('투자 선택에 기여하는 근거','investmentRelevance'):''),'memory-new',id);
  }
  function validateCandidateForm(id){const c=choose(data.memoryCandidates,id);return form('학습 후보 검증',select('지식 유형','knowledgeType',knowledgeTypes,c.knowledgeType||'HYPOTHESIS')+area('검증 요약','summary')+area('반례·적용이 깨지는 조건','counterexamples')+area('표본 외 관측 근거·추가 확인 계획','forwardEvidence')+area('검증 계획','validationPlan',c.validationPlan||'검증 기간·대조 조건·비용 가정·판정 기준을 기록한다.')+area('불확실성과 남은 확인','uncertainty',c.uncertainty||'표본 수와 독립성, 미래 조건 변화가 미치는 영향을 검토한다.'),'memory-validate',id);}
  function reviewExperience(id){const e=choose(data.experiences,id);if(e?.experienceType==='EXECUTION_OPERATION'&&e.status==='AWAITING_OBSERVATION')return form('운영 후속 관측',field('관측 시각 (UTC)','asOf',new Date().toISOString().slice(0,16),'datetime-local','required')+area('발생 원인·복구 결과','details'),'observe-operation',id);if(e?.status==='OBSERVED')return evaluateExperienceForm(id);if(e?.status==='EVALUATED')return memoryCandidateForm(id);}
