  function configureBotForm(id){const d=choose(data.deployments,id),group=(data.comparisons||[]).find(g=>g.members.some(m=>m.deploymentId===id));if(group)return hooks.open('적용 버전',`<p class="readable">비교 운용은 시작할 때 선택한 프로필·전략·프리셋 버전을 사용합니다. 새 조합은 새 비교 운용으로 시작하세요. 승인 기억은 모의투자의 기억 적용에서 다음 사용 가능 봉부터 반영할 수 있습니다.</p>${details(d)}`);return form('적용 버전 변경','<p class="tiny full">일시중지한 봇의 다음 전략 실행부터 적용합니다.</p>'+select('프로필 버전','investmentProfileVersionId',data.profileVersions.filter(v=>v.entityId===d.investmentProfileId).map(v=>[v.id,'v'+v.version]),d.investmentProfileVersionId)+select('전략 버전','strategyVersionId',data.strategyVersions.map(v=>[v.id,name('strategies',v.entityId)+' v'+v.version]),d.strategyVersionId)+select('운용 프리셋 버전','riskPresetVersionId',data.riskPresetVersions.map(v=>[v.id,name('riskPresets',v.entityId)+' v'+v.version]),d.riskPresetVersionId)+select('승인 기억 버전','memoryVersionId',data.memoryVersions.filter(v=>v.investmentProfileId===d.investmentProfileId).map(v=>[v.id,'v'+v.version+' · '+v.items.length+'건']),d.memoryVersionId),'bot-configure',id);}
  function noteForm(id){const n=id?choose(data.knowledge.items,id):{};form(id?'노트 편집':'노트 추가',field('제목','title',n.title||'','text','required maxlength="120"')+area('본문','text',n.text||'',12000)+select('분류','kind',[['fact','사실'],['observation','근거'],['hypothesis','가설'],['rule','규칙']],n.kind||'hypothesis')+field('출처명','sourceTitle',n.sourceTitle||'사용자 메모','text','required')+field('출처 위치','sourceLocator',n.sourceLocator||'사용자 입력')+select('참조 근거','evidenceId',[['','없음'],...data.knowledge.items.filter(v=>v.id!==id).map(v=>[v.id,v.title])],n.evidenceIds?.[0]),'note',id);}
  function profileForm(id){const p=id?choose(data.investmentProfiles,id):null,v=p?getVersion(data.profileVersions,p).settings:{};form(p?'프로필 편집':'프로필 추가',field('이름','name',p?.name||'','','required maxlength="120"')+select('투자 기간','horizon',[['1h','1시간봉'],['4h','4시간'],['1d','일 단위'],['multi-day','여러 날']],v.horizon)+field('성향','style',v.style||'custom')+field('우선 근거 (쉼표로 구분)','evidencePreferences',v.evidencePreferences?.join(', ')||'가격 구조')+area('투자 원칙','philosophy',v.philosophy||'확인된 추세와 반대 근거를 함께 검토한다.')+area('운용 규율','discipline',v.discipline||'손실 한도·비용·보유 논제 훼손을 확인한다.'),'profile',id);}
  function presetForm(id){const p=id?choose(data.riskPresets,id):null,v=p?getVersion(data.riskPresetVersions,p).settings:{normalBuyWeight:.5,clutchBuyWeight:1,sellWeight:.25,maxExposure:1,maxOrderWeight:1,dailyLossLimit:.05,minNotional:10,maxFeeBps:100,maxSlippageBps:100};const names={normalBuyWeight:'보통 매수 비중',clutchBuyWeight:'기회 집중 비중',sellWeight:'매도 후 유지 비중',maxExposure:'최대 보유 비중',maxOrderWeight:'1회 주문 비중',dailyLossLimit:'일일 손실 한도'};form('운용 프리셋',field('이름','name',p?.name||'','','required')+Object.entries(names).map(([k,t])=>field(t+' (%)',k,v[k]*100,'number','min="0" max="100" step="0.1" required')).join('')+field('최소 주문 금액 (USDT)','minNotional',v.minNotional,'number','min="0" required')+field('수수료 상한 (bp)','maxFeeBps',v.maxFeeBps,'number','min="0" max="1000" required')+field('슬리피지 상한 (bp)','maxSlippageBps',v.maxSlippageBps,'number','min="0" max="1000" required'),'preset',id);}
