    if(op==='shared-attach')return form('운용 봇 자금 연결',select('운용 봇','deploymentId',data.deployments.filter(d=>!d.sharedAccountId&&!choose(data.accounts,d.accountId).ledger.length).map(d=>[d.id,d.name+' · '+num(choose(data.accounts,d.accountId).initialEquity,0)+' USDT'])),'shared-attach',id);
