    if(op==='market-check'){busy=true;redraw();try{const v=await request('/api/workspace/connections/market'),c=v.connection,provider=c.providerLabel||consoleProviderLabel(c.provider||market?.provider),origin=c.origin||market?.origin;return hooks.open('시세 연결 확인','<p class="callout">'+esc(c.status==='connected'?'공개 시세 연결 완료':c.message)+'</p><p>'+esc(provider)+' BTC / USDT · '+when(c.checkedAt)+'</p>'+(origin?'<p class="tiny muted">수집 주소 '+esc(origin)+'</p>':'')+(c.status==='connected'?'<p>최근 확정 봉 '+when(c.latestClosedAsOf)+' · 4시간봉 '+c.candleCount+'개 · 일봉 '+c.dailyCandleCount+'개</p>':'<p>오류 코드 '+esc(c.code)+'</p>')+'<p class="tiny muted">현재 실시간 연결의 진단 결과입니다. 과거 재생은 별도 Binance 자료를 사용하며, 실행·후속 진단의 출처는 해당 기록에서 확인합니다.</p>'+details(c));}finally{busy=false;redraw();}}
