    if(op==='preset-new'||op==='preset-edit')return presetForm(id);if(op==='strategy-new'||op==='strategy-edit')return strategyForm(id);if(op==='bot-new')return botForm();
    if(op==='bot-evaluate'){if(choose(data.deployments,id).experimentType==='FORWARD_PAPER')return await action('',{deploymentId:id},'/api/workspace/evaluate');const input=document.querySelector(`[data-bot-time="${id}"]`);const asOf=new Date(input.value+'Z').toISOString();times.set(id,input.value);return await action('',{deploymentId:id,...(choose(data.deployments,id).experimentType==='FORWARD_PAPER'?{}:{asOf})},'/api/workspace/evaluate');}
