    if(op==='source-new')return form('자료 가져오기',field('제목','title','','text','required')+select('형식','mimeType',[['text/markdown','Markdown'],['text/plain','텍스트'],['application/json','JSON'],['text/csv','CSV']])+field('출처 주소','sourceUri','','url')+field('원문 위치','sourceLocator','사용자 입력')+area('원본 내용','text','',80000),'source');
